-- AI/ML pathway (Cipher Division) Act 6 -- "The Split" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. Closes Arc I
-- ("Learn to See Data"). Builds on the World row already inserted by
-- 20260811100000_ai_acts6_36_spine.sql (world-ai-the-split, act-ai-1).

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-the-split', 'world-ai-the-split', 'the-split', '6A - The Split', 'Before Cipher Division builds anything on the recovered fragments, the data has to be split into training, validation and test sets that never mix -- and the team has to prove any good-looking result actually survives a fair, leakage-free evaluation.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-the-split-1', 'campaign-ai-the-split', 'three-piles', 'Three Piles', 'Three purposeful piles instead of one dataset -- training data to learn from, validation data to tune against, and test data touched exactly once.', 1),
  ('operation-ai-the-split-2', 'campaign-ai-the-split', 'the-honest-number', 'The Honest Number', 'Leakage, shift, baselines and reproducibility -- everything standing between an exciting number and an honest one.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-the-split-01', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-1', 'training-data', 'Training Data', 'The recovered fragments passed cleanup. Before anyone trains a single model on them, the data has to be split into pieces that never mix -- or the result will not mean anything.', 'beginner', ARRAY['maya','arjun'], null, null, '{"type":"simulation","simulationId":"training-data-sim"}'::jsonb, '{"xp":120,"credits":20}'::jsonb, false, 1),
  ('mission-ai-the-split-02', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-1', 'validation-data', 'Validation Data', 'A model can be tuned and compared against itself without ever touching the test set -- if there is a second pile set aside just for that.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-split-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"validation-data-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 2),
  ('mission-ai-the-split-03', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-1', 'test-data', 'Test Data', 'Test data gets touched exactly once. Everything about how it is used depends on that one rule holding.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-split-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"test-data-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 3),
  ('mission-ai-the-split-04', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-1', 'random-splits', 'Random Splits', 'The simplest way to split a dataset is also the easiest one to get wrong when a class barely shows up at all.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-split-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"random-splits-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 4),
  ('mission-ai-the-split-05', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-1', 'stratification', 'Stratification', 'A random split can accidentally erase a rare class from an entire pile. Stratification is the fix that keeps every pile honest.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-split-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"stratification-sim"}'::jsonb, '{"xp":140,"credits":30}'::jsonb, false, 5),
  ('mission-ai-the-split-06', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-1', 'time-based-splits', 'Time-Based Splits', 'Some data has a clock built into it. Split it the wrong way and the model quietly learns to predict the past using the future.', 'beginner', ARRAY['arjun','byte'], '{"requiredMissionIds":["mission-ai-the-split-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"time-based-splits-sim"}'::jsonb, '{"xp":150,"credits":30}'::jsonb, false, 6),
  ('mission-ai-the-split-07', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-2', 'data-leakage', 'Data Leakage', 'Leakage is any way for information the model should not have to sneak into training -- and the recovered fragments already have a known way for it to happen.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-split-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"data-leakage-sim"}'::jsonb, '{"xp":150,"credits":30}'::jsonb, false, 7),
  ('mission-ai-the-split-08', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-2', 'target-leakage', 'Target Leakage', 'Some leaks hide inside a single innocent-looking column that only exists because the outcome already happened.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-split-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"target-leakage-sim"}'::jsonb, '{"xp":160,"credits":35}'::jsonb, false, 8),
  ('mission-ai-the-split-09', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-2', 'distribution-shift', 'Distribution Shift', 'A model trained on one slice of the world and tested on another will not be judged fairly, in either direction.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-split-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"distribution-shift-sim"}'::jsonb, '{"xp":160,"credits":35}'::jsonb, false, 9),
  ('mission-ai-the-split-10', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-2', 'baselines', 'Baselines', 'A number means nothing on its own. It means something next to the simplest model that could have produced it.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-split-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"baselines-sim"}'::jsonb, '{"xp":170,"credits":35}'::jsonb, false, 10),
  ('mission-ai-the-split-11', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-2', 'reproducibility', 'Reproducibility', 'A result nobody else can reproduce is not evidence. It is an anecdote with a percentage sign attached.', 'beginner', ARRAY['arjun','byte'], '{"requiredMissionIds":["mission-ai-the-split-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"reproducibility-sim"}'::jsonb, '{"xp":170,"credits":40}'::jsonb, false, 11),
  ('mission-ai-the-split-12', 'world-ai-the-split', 'campaign-ai-the-split', 'operation-ai-the-split-2', 'the-99-percent-model', 'The 99% Model', 'The quick first model on the recovered fragments just scored 99%. Cipher Division has to prove that number is real before anyone is allowed to believe it.', 'boss', ARRAY['maya','arjun'], '{"requiredMissionIds":["mission-ai-the-split-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-99-percent-model-boss-sim"}'::jsonb, '{"xp":550,"credits":120,"badgeIds":["the-99-percent-model"],"skillXp":{"data_engineering_ml":45,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-the-split-01', 1, 'maya', 'The cleaned fragments -- the ones that might be Echo''s original training data -- passed audit. Missing values patched, duplicates resolved, corrupted values flagged. Everyone in this room wants to build something with them right now.'),
  ('mission-ai-the-split-01', 2, 'arjun', 'I want that too. Wanting it does not buy us the right to skip the next step. Before any model touches this data, it gets split -- properly -- into pieces that never mix.'),
  ('mission-ai-the-split-01', 3, 'maya', 'Say it plainly for the room. Half of Cipher Division has never heard the phrase training data and needs the real definition, not the shorthand.'),
  ('mission-ai-the-split-01', 4, 'arjun', 'Training data is the slice of the dataset a model actually learns from -- the examples it sees, predicts on, and gets corrected against, over and over, while its parameters are being adjusted. It is usually the largest of the piles, and the only one whose answers the model is allowed to look at while learning.'),
  ('mission-ai-the-split-01', 5, 'arjun', 'Everything else in this Act exists to answer one question honestly: once training data has taught the model something, how do we find out whether it actually learned something real?'),

  ('mission-ai-the-split-02', 1, 'arjun', 'Training data teaches the model. Validation data is the second pile -- used to check performance while still tuning it, comparing versions, adjusting settings, all without ever touching the pile set aside for the final answer.'),
  ('mission-ai-the-split-02', 2, 'arjun', 'Treat it like an honest practice test. You look at the results and learn from them, but the model''s parameters are never trained directly on validation rows.'),
  ('mission-ai-the-split-02', 3, 'arjun', 'The failure mode is subtle. Keep re-tuning against validation scores long enough, and validation quietly turns into training data by another name -- its numbers stop meaning what you think they mean.'),

  ('mission-ai-the-split-03', 1, 'arjun', 'Test data is the third pile, and it has one rule that matters more than any other: it gets touched exactly once, at the very end, after every tuning decision is already locked in.'),
  ('mission-ai-the-split-03', 2, 'arjun', 'Look at test scores in the middle of development, even once, even by accident, and you have started tuning against it -- and it stops being able to answer the question it exists to answer.'),
  ('mission-ai-the-split-03', 3, 'arjun', 'Three piles, three jobs. Training teaches. Validation tunes. Test tells the truth, and only gets asked once.'),

  ('mission-ai-the-split-04', 1, 'arjun', 'The simplest way to create the three piles is a random split -- shuffle every row, then cut it into training, validation and test by percentage, commonly something like 70/15/15 or 80/10/10.'),
  ('mission-ai-the-split-04', 2, 'arjun', 'Random splitting works well when the data is large and the outcome you care about is reasonably common. It starts to fail quietly the moment either of those stops being true.'),

  ('mission-ai-the-split-05', 1, 'arjun', 'Stratification fixes exactly the failure random splitting just showed. Instead of shuffling blind, a stratified split preserves each class''s proportion in every pile -- training, validation and test all get roughly the same mix.'),
  ('mission-ai-the-split-05', 2, 'arjun', 'If the rare class is 4% of the whole dataset, a proper stratified split keeps it at roughly 4% in training, 4% in validation, and 4% in test -- not zero in one pile and double in another.'),

  ('mission-ai-the-split-06', 1, 'arjun', 'Some data has a clock built into it. The recovered fragments carry timestamps spanning the original collection window -- and that changes the rules.'),
  ('mission-ai-the-split-06', 2, 'byte', 'Shuffle time-ordered data before splitting, and a model can end up training on rows from next month while being tested on rows from last month. It would be learning to predict the past using the future.'),
  ('mission-ai-the-split-06', 3, 'arjun', 'A time-based split fixes that: training data comes from the earliest period, validation from the period after that, test from the most recent period -- always in that order, never shuffled across the boundary.'),

  ('mission-ai-the-split-07', 1, 'arjun', 'Data leakage is the umbrella term for all of this: any way information sneaks into training or evaluation that would not actually be available in a fair, honest test.'),
  ('mission-ai-the-split-07', 2, 'arjun', 'It is not one bug. It is a whole family of them -- duplicated rows landing in both training and test, features that peek at the future, splits that ignore natural boundaries in the data. Any of them can make a model look far better than it actually is.'),
  ('mission-ai-the-split-07', 3, 'arjun', 'Which brings us back to something Cipher Division already found. Records-recovery flagged duplicated blocks during Act 5''s cleanup. If those duplicates ever end up split across training and test instead of staying together in one pile, that is leakage -- and it would make a model look like it learned something it never actually learned.'),

  ('mission-ai-the-split-08', 1, 'arjun', 'Target leakage is a specific, sneaky flavor of leakage: a feature that is only known, or only exists, because the outcome already happened -- so the model is not predicting the answer, it is reading it off a proxy column.'),
  ('mission-ai-the-split-08', 2, 'arjun', 'Classic example: predicting whether a patient will be hospitalized, using a feature called days-in-hospital. That feature does not exist until after the outcome is already known. Feed it in, and the model looks brilliant while learning nothing useful.'),

  ('mission-ai-the-split-09', 1, 'arjun', 'Distribution shift is when the data a model was trained on no longer matches the data it is actually being evaluated or used on -- same columns, different underlying population.'),
  ('mission-ai-the-split-09', 2, 'arjun', 'It can come from time, from the recovery batch a fragment came out of, or from where the data was collected. However it happens, a model trained on one distribution and judged against a very different one will not be judged fairly, in either direction.'),

  ('mission-ai-the-split-10', 1, 'arjun', 'A number alone means nothing. 91% accuracy sounds great, until you learn the simplest possible model -- always guessing the majority class -- already gets 90% on that same data.'),
  ('mission-ai-the-split-10', 2, 'arjun', 'A baseline is the simplest reasonable model you can build: predict the majority class, predict the mean, guess randomly within known proportions. Every real model has to beat its baseline by a meaningful margin, or it is not actually adding value.'),

  ('mission-ai-the-split-11', 1, 'arjun', 'A result nobody else can reproduce is not evidence. It is an anecdote with a percentage sign attached.'),
  ('mission-ai-the-split-11', 2, 'byte', 'Reproducibility means someone else -- or you, next week -- can re-run the exact same split and the exact same training run and get the exact same result. That takes a fixed random seed, a saved data version, and a recorded configuration, not memory.'),
  ('mission-ai-the-split-11', 3, 'arjun', 'Skip any one of those and a result becomes unverifiable. Which, conveniently, is exactly the property a fake result needs to survive scrutiny.'),

  ('mission-ai-the-split-12', 1, 'arjun', 'The quick first model is done. Trained on the recovered fragments, evaluated the same afternoon. It scored 99% accuracy.'),
  ('mission-ai-the-split-12', 2, 'maya', 'Ninety-nine percent, on data that was still being called garbage six days ago. Before anyone repeats that number out loud, prove to me it is real.'),
  ('mission-ai-the-split-12', 3, 'arjun', 'Three checks: how the split was actually done, whether Act 5''s duplicated blocks stayed contained inside one pile, and what a fair baseline would have scored on the same evaluation.'),
  ('mission-ai-the-split-12', 4, 'maya', 'Excitement about a good number is not evidence. Only a correctly isolated evaluation is. Run the audit.'),
  ('mission-ai-the-split-12', 5, 'arjun', 'Whatever the verdict, this closes what Act 5 opened. We finally have data we might trust. Now we find out whether we can trust what we measure on it.'),
  ('mission-ai-the-split-12', 6, 'maya', 'And once we can trust the measurement, the real question stops being whether this data is clean, and starts being what Cipher Division can actually predict with it.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-the-split-01-o1', 'mission-ai-the-split-01', 1, 'Define training data', 'Identify the accurate definition of training data.'),
  ('mission-ai-the-split-01-o2', 'mission-ai-the-split-01', 2, 'Explain why holding nothing back fails', 'Find the evidence that explains why training and testing on the same rows proves nothing.'),

  ('mission-ai-the-split-02-o1', 'mission-ai-the-split-02', 1, 'Define validation data', 'Identify what validation data is actually used for.'),
  ('mission-ai-the-split-02-o2', 'mission-ai-the-split-02', 2, 'Spot the quiet leak', 'Identify what happens to a validation set that gets used to endlessly re-tune a model.'),

  ('mission-ai-the-split-03-o1', 'mission-ai-the-split-03', 1, 'Define test data', 'Identify the accurate definition of test data and its one rule.'),
  ('mission-ai-the-split-03-o2', 'mission-ai-the-split-03', 2, 'Sort the three piles', 'Sort each described use into training, validation, or test.'),

  ('mission-ai-the-split-04-o1', 'mission-ai-the-split-04', 1, 'Define random splitting', 'Identify what a random split actually does to a dataset.'),
  ('mission-ai-the-split-04-o2', 'mission-ai-the-split-04', 2, 'Find where it breaks', 'Identify the scenario where a plain random split is most likely to fail silently.'),

  ('mission-ai-the-split-05-o1', 'mission-ai-the-split-05', 1, 'Define stratification', 'Identify what a stratified split actually preserves.'),
  ('mission-ai-the-split-05-o2', 'mission-ai-the-split-05', 2, 'Apply it to the fragments', 'Decide which recovered-data scenario most needs stratification.'),

  ('mission-ai-the-split-06-o1', 'mission-ai-the-split-06', 1, 'Define time-based splitting', 'Identify why chronological order matters for splitting time-ordered data.'),
  ('mission-ai-the-split-06-o2', 'mission-ai-the-split-06', 2, 'Match strategy to scenario', 'Match each dataset scenario to the splitting strategy it actually needs.'),

  ('mission-ai-the-split-07-o1', 'mission-ai-the-split-07', 1, 'Define leakage', 'Identify the accurate definition of data leakage.'),
  ('mission-ai-the-split-07-o2', 'mission-ai-the-split-07', 2, 'Spot the leakage risk', 'Identify the evidence that shows a real leakage risk in how the fragments were split.'),

  ('mission-ai-the-split-08-o1', 'mission-ai-the-split-08', 1, 'Define target leakage', 'Identify what makes target leakage different from ordinary leakage.'),
  ('mission-ai-the-split-08-o2', 'mission-ai-the-split-08', 2, 'Find the leaking feature', 'Identify which candidate feature would leak the target.'),

  ('mission-ai-the-split-09-o1', 'mission-ai-the-split-09', 1, 'Define distribution shift', 'Identify the accurate definition of distribution shift.'),
  ('mission-ai-the-split-09-o2', 'mission-ai-the-split-09', 2, 'Spot the shift', 'Identify the evidence that shows a real distribution shift in the recovered fragments.'),

  ('mission-ai-the-split-10-o1', 'mission-ai-the-split-10', 1, 'Define baselines', 'Identify why a baseline model matters before judging a real one.'),
  ('mission-ai-the-split-10-o2', 'mission-ai-the-split-10', 2, 'Judge the number', 'Decide whether a model''s score actually beats its baseline.'),

  ('mission-ai-the-split-11-o1', 'mission-ai-the-split-11', 1, 'Define reproducibility', 'Identify what makes a machine learning result reproducible.'),
  ('mission-ai-the-split-11-o2', 'mission-ai-the-split-11', 2, 'Find the bug', 'Debug the split function that is quietly breaking reproducibility.'),

  ('mission-ai-the-split-12-o1', 'mission-ai-the-split-12', 1, 'Examine the split methodology', 'Determine whether the quick model''s split actually isolated evaluation data the way a real split must.'),
  ('mission-ai-the-split-12-o2', 'mission-ai-the-split-12', 2, 'Trace the duplicated-block leak', 'Find the evidence connecting Act 5''s duplicated blocks to this model''s inflated score.'),
  ('mission-ai-the-split-12-o3', 'mission-ai-the-split-12', 3, 'Demand a fair baseline', 'Determine what a trustworthy baseline comparison actually shows about the 99% score.'),
  ('mission-ai-the-split-12-o4', 'mission-ai-the-split-12', 4, 'Synthesize the verdict', 'Having audited the split, the leakage, and the baseline, state Cipher Division''s verdict on the 99% score.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-the-split-01-o1-c1', 'mission-ai-the-split-01-o1', 1, 'multiple_choice', 'Training data is best described as...', '{"question":"Training data is best described as...","options":[{"id":"a","text":"The entire dataset, used for everything from learning to final reporting"},{"id":"b","text":"The portion of data a model directly learns from, with its correct labels visible during training"},{"id":"c","text":"Data collected after the model is deployed"},{"id":"d","text":"A random sample used only to name the columns"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-01-o2-c1', 'mission-ai-the-split-01-o2', 1, 'investigation', 'Why is training and testing on the exact same rows meaningless as a way to check whether the model actually learned anything?', '{"evidence":[{"id":"e1","label":"Team proposal","detail":"Use all 6,000 cleaned rows to train the model, then re-run those same 6,000 rows through it to report accuracy"},{"id":"e2","label":"Arjun''s note","detail":"A model graded on rows it was trained on can simply memorize them -- a perfect-looking score would not prove it learned a real pattern"},{"id":"e3","label":"Facilities memo","detail":"Cipher Labs'' cooling systems are running within normal range"}],"question":"Why is training and testing on the exact same rows meaningless as a way to check whether the model actually learned anything?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-the-split-02-o1-c1', 'mission-ai-the-split-02-o1', 1, 'multiple_choice', 'Validation data is best used to...', '{"question":"Validation data is best used to...","options":[{"id":"a","text":"Train the model''s parameters directly, just like training data"},{"id":"b","text":"Tune settings and compare model versions during development, without ever touching the final test set"},{"id":"c","text":"Report the final number anyone outside the team will see"},{"id":"d","text":"Replace training data once it runs out"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-02-o2-c1', 'mission-ai-the-split-02-o2', 1, 'multiple_choice', 'A team tunes hyperparameters against validation accuracy fifty separate times until it looks perfect. What has actually happened to the validation set?', '{"question":"A team tunes hyperparameters against validation accuracy fifty separate times until it looks perfect. What has actually happened to the validation set?","options":[{"id":"a","text":"Nothing, validation sets can be reused without limit"},{"id":"b","text":"It has effectively become part of training by proxy -- its score is no longer an honest estimate of performance on unseen data"},{"id":"c","text":"It has become the new test set"},{"id":"d","text":"It has been converted into training data automatically"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-the-split-03-o1-c1', 'mission-ai-the-split-03-o1', 1, 'multiple_choice', 'Test data is best described as...', '{"question":"Test data is best described as...","options":[{"id":"a","text":"A second validation set that can be checked as often as needed"},{"id":"b","text":"The pile of data held back and evaluated exactly once, after all tuning decisions are final, to estimate real-world performance"},{"id":"c","text":"Whichever rows happen to be left over"},{"id":"d","text":"Data collected after deployment"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-03-o2-c1', 'mission-ai-the-split-03-o2', 1, 'drag_and_drop', 'Sort each described use into training, validation, or test.', '{"items":[{"id":"i1","text":"Adjusting a model''s parameters directly during learning"},{"id":"i2","text":"Comparing two candidate model configurations before picking one"},{"id":"i3","text":"Reporting the single final accuracy number Cipher Division will act on"},{"id":"i4","text":"Early-stopping training once performance on this pile stops improving"}],"targets":[{"id":"training","label":"Training"},{"id":"validation","label":"Validation"},{"id":"test","label":"Test"}]}'::jsonb, '{"correctMapping":{"i1":"training","i2":"validation","i3":"test","i4":"validation"}}'::jsonb),

  ('mission-ai-the-split-04-o1-c1', 'mission-ai-the-split-04-o1', 1, 'multiple_choice', 'A random train/validation/test split works by...', '{"question":"A random train/validation/test split works by...","options":[{"id":"a","text":"Sorting rows by date before cutting them into piles"},{"id":"b","text":"Shuffling rows and dividing them into piles by percentage, with no regard to any specific column"},{"id":"c","text":"Choosing only rows the model already predicts correctly for training"},{"id":"d","text":"Duplicating every row into all three piles"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-04-o2-c1', 'mission-ai-the-split-04-o2', 1, 'investigation', 'In which dataset is a plain random split most likely to accidentally leave one or more piles with almost no examples of the rare class?', '{"evidence":[{"id":"e1","label":"Dataset note","detail":"10,000 rows, roughly balanced 50/50 between two outcome classes"},{"id":"e2","label":"Dataset note","detail":"10,000 rows, but only 40 rows belong to the rare class of interest -- the other 9,960 are the common class"},{"id":"e3","label":"Dataset note","detail":"10,000 rows collected over a single afternoon with no meaningful time structure"}],"question":"In which dataset is a plain random split most likely to accidentally leave one or more piles with almost no examples of the rare class?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-the-split-05-o1-c1', 'mission-ai-the-split-05-o1', 1, 'multiple_choice', 'A stratified split is designed to...', '{"question":"A stratified split is designed to...","options":[{"id":"a","text":"Preserve the proportion of each class across every pile"},{"id":"b","text":"Guarantee every pile is exactly the same size"},{"id":"c","text":"Remove the rare class entirely so it cannot cause errors"},{"id":"d","text":"Sort rows by timestamp before splitting"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-the-split-05-o2-c1', 'mission-ai-the-split-05-o2', 1, 'investigation', 'Which of these recovered-fragment scenarios most needs a stratified split rather than a plain random one?', '{"evidence":[{"id":"e1","label":"Fragment audit","detail":"Outcome label is roughly 50/50 across the recovered rows"},{"id":"e2","label":"Fragment audit","detail":"Outcome label is 96% one value and 4% the other across the recovered rows"},{"id":"e3","label":"Fragment audit","detail":"All rows share the identical outcome label"}],"question":"Which of these recovered-fragment scenarios most needs a stratified split rather than a plain random one?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-the-split-06-o1-c1', 'mission-ai-the-split-06-o1', 1, 'multiple_choice', 'For data with a genuine time order, why does a time-based split matter instead of a plain random one?', '{"question":"For data with a genuine time order, why does a time-based split matter instead of a plain random one?","options":[{"id":"a","text":"It does not matter, time order is irrelevant to splitting"},{"id":"b","text":"A random split can let the model train on future rows and get tested on earlier rows, letting future information leak backward into training"},{"id":"c","text":"It only matters for image data"},{"id":"d","text":"Time-based splits always produce more accurate models"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-06-o2-c1', 'mission-ai-the-split-06-o2', 1, 'drag_and_drop', 'Match each dataset scenario to the splitting strategy it actually needs.', '{"items":[{"id":"i1","text":"A large, balanced dataset with no meaningful time order and no rare classes"},{"id":"i2","text":"A dataset where the outcome of interest appears in only 3% of rows"},{"id":"i3","text":"Timestamped sensor readings feeding a model that will only ever predict forward in time"},{"id":"i4","text":"A rare-disease diagnosis dataset where positive cases are less than 2% of all rows"},{"id":"i5","text":"A log of daily transactions where next month must never be predicted using next month''s own data"},{"id":"i6","text":"Survey responses, well balanced, all collected in one single sitting with no order to preserve"}],"targets":[{"id":"random","label":"Random split"},{"id":"stratified","label":"Stratified split"},{"id":"time-based","label":"Time-based split"}]}'::jsonb, '{"correctMapping":{"i1":"random","i2":"stratified","i3":"time-based","i4":"stratified","i5":"time-based","i6":"random"}}'::jsonb),

  ('mission-ai-the-split-07-o1-c1', 'mission-ai-the-split-07-o1', 1, 'multiple_choice', 'Data leakage is best defined as...', '{"question":"Data leakage is best defined as...","options":[{"id":"a","text":"Any missing value in a dataset"},{"id":"b","text":"Information reaching training or evaluation that would not genuinely be available under fair, honest conditions"},{"id":"c","text":"A dataset that is too large"},{"id":"d","text":"A model that trains too slowly"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-07-o2-c1', 'mission-ai-the-split-07-o2', 1, 'investigation', 'Which evidence directly shows a real leakage risk in how the recovered fragments were split?', '{"evidence":[{"id":"e1","label":"Cleanup report","detail":"Records-recovery flagged duplicated blocks during Act 5''s audit -- the same underlying record appearing more than once due to overlapping recovery imaging"},{"id":"e2","label":"Split log","detail":"The quick first split randomly shuffled all rows, including duplicates, before dividing them into training and test"},{"id":"e3","label":"Storage log","detail":"Drives were imaged bit-for-bit before analysis"}],"question":"Which evidence directly shows a real leakage risk in how the recovered fragments were split?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-the-split-08-o1-c1', 'mission-ai-the-split-08-o1', 1, 'multiple_choice', 'Target leakage specifically refers to...', '{"question":"Target leakage specifically refers to...","options":[{"id":"a","text":"Any column with missing values"},{"id":"b","text":"A feature that is only available or only exists after the outcome has already occurred, effectively encoding the answer"},{"id":"c","text":"Splitting data randomly instead of by time"},{"id":"d","text":"Using too many features in a model"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-08-o2-c1', 'mission-ai-the-split-08-o2', 1, 'investigation', 'Which candidate feature would leak the target -- the outcome being predicted?', '{"evidence":[{"id":"e1","label":"Feature candidate: heart_rate_at_admission","detail":"Recorded the moment the patient arrives, before any outcome is known"},{"id":"e2","label":"Feature candidate: discharge_summary_flag","detail":"Only gets set after the patient''s case is fully closed out -- which happens only after the outcome being predicted is already known"},{"id":"e3","label":"Feature candidate: patient_age","detail":"Known from intake records, unrelated to any outcome"}],"question":"Which candidate feature would leak the target -- the outcome being predicted?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-the-split-09-o1-c1', 'mission-ai-the-split-09-o1', 1, 'multiple_choice', 'Distribution shift is best described as...', '{"question":"Distribution shift is best described as...","options":[{"id":"a","text":"A dataset with missing values"},{"id":"b","text":"A mismatch between the data a model was trained on and the data it is being evaluated or used on"},{"id":"c","text":"A model that trains too slowly"},{"id":"d","text":"A synonym for data leakage"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-09-o2-c1', 'mission-ai-the-split-09-o2', 1, 'investigation', 'Which evidence shows a real distribution shift between parts of the recovered fragments?', '{"evidence":[{"id":"e1","label":"Batch comparison","detail":"Fragments recovered from the earliest storage batch show a very different feature distribution than fragments recovered from the most recent batch"},{"id":"e2","label":"Format check","detail":"All fragments share the same column names and types"},{"id":"e3","label":"Storage log","detail":"All drives were imaged using the identical recovery procedure"}],"question":"Which evidence shows a real distribution shift between parts of the recovered fragments?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-the-split-10-o1-c1', 'mission-ai-the-split-10-o1', 1, 'multiple_choice', 'A baseline model is best used to...', '{"question":"A baseline model is best used to...","options":[{"id":"a","text":"Replace the real model entirely once it exists"},{"id":"b","text":"Give a simple reference point that a real model''s score has to meaningfully beat to prove it learned something useful"},{"id":"c","text":"Only apply to image data"},{"id":"d","text":"Guarantee the real model will perform better"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-10-o2-c1', 'mission-ai-the-split-10-o2', 1, 'investigation', 'Given the class split and the baseline score, does the 91%-accuracy model actually demonstrate meaningful skill?', '{"evidence":[{"id":"e1","label":"Dataset note","detail":"The outcome column is 90% one class and 10% the other"},{"id":"e2","label":"Model report","detail":"The trained model scores 91% accuracy"},{"id":"e3","label":"Baseline report","detail":"Always predicting the majority class alone scores 90% accuracy on the same data"}],"question":"Given the class split and the baseline score, does the 91%-accuracy model actually demonstrate meaningful skill?"}'::jsonb, '{"requiredEvidenceIds":["e3"]}'::jsonb),

  ('mission-ai-the-split-11-o1-c1', 'mission-ai-the-split-11-o1', 1, 'multiple_choice', 'A reproducible result requires...', '{"question":"A reproducible result requires...","options":[{"id":"a","text":"A confident-sounding report and nothing else"},{"id":"b","text":"A fixed random seed, a versioned dataset, and a recorded configuration, so the same run can be repeated and verified"},{"id":"c","text":"Running the model only once, ever"},{"id":"d","text":"Keeping the exact split and code secret"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-split-11-o2-c1', 'mission-ai-the-split-11-o2', 1, 'code_debugging', 'This split function is supposed to produce the same train/test split every time it runs on the same data. Which line contains the bug?', '{"language":"python","code":"def make_split(data):\n    shuffled = data.sample(frac=1)\n    cutoff = int(len(shuffled) * 0.8)\n    train = shuffled[:cutoff]\n    test = shuffled[cutoff:]\n    return train, test","question":"This split function is supposed to produce the same train/test split every time it runs on the same data. Which line contains the bug?"}'::jsonb, '{"requiredLineIds":["    shuffled = data.sample(frac=1)"]}'::jsonb),

  ('mission-ai-the-split-12-o1-c1', 'mission-ai-the-split-12-o1', 1, 'investigation', 'Which evidence shows a real problem with how the quick model''s split was done?', '{"evidence":[{"id":"e1","label":"Split log","detail":"The quick model shuffled all 6,000 cleaned rows together and cut them 80/20 into training and test, with no grouping by underlying record or recovery block"},{"id":"e2","label":"Timing note","detail":"The whole quick build was completed in one afternoon"},{"id":"e3","label":"Storage log","detail":"Drives were imaged bit-for-bit before analysis"}],"question":"Which evidence shows a real problem with how the quick model''s split was done?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-the-split-12-o2-c1', 'mission-ai-the-split-12-o2', 1, 'investigation', 'Which evidence directly explains why the 99% score is inflated by leakage?', '{"evidence":[{"id":"e1","label":"Cleanup report (Act 5)","detail":"Records-recovery flagged duplicated blocks -- the same underlying record appearing more than once from overlapping recovery imaging"},{"id":"e2","label":"Split audit","detail":"Cross-referencing the training and test sets shows several duplicated-block records present in both piles -- the model was tested on rows nearly identical to ones it trained on"},{"id":"e3","label":"Model architecture note","detail":"The quick model used a standard off-the-shelf classifier with default settings"}],"question":"Which evidence directly explains why the 99% score is inflated by leakage?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-the-split-12-o3-c1', 'mission-ai-the-split-12-o3', 1, 'investigation', 'Once evaluated fairly, what does the honest comparison actually show about this model?', '{"evidence":[{"id":"e1","label":"Baseline report","detail":"Predicting the majority class alone scores 71% on a properly isolated evaluation set"},{"id":"e2","label":"Re-split evaluation","detail":"After removing duplicated-block records from training and re-splitting cleanly, the same model architecture scores 76% on a properly isolated test set"},{"id":"e3","label":"Original report","detail":"The quick model scored 99% before duplicates were removed from the split"}],"question":"Once evaluated fairly, what does the honest comparison actually show about this model?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-the-split-12-o4-c1', 'mission-ai-the-split-12-o4', 1, 'boss_encounter', 'Having audited the split, the leakage, and the baseline, state Cipher Division''s verdict on the 99% score.', '{"stages":[{"objectiveRef":"mission-ai-the-split-12-o1","label":"Examine the split methodology"},{"objectiveRef":"mission-ai-the-split-12-o2","label":"Trace the duplicated-block leak"},{"objectiveRef":"mission-ai-the-split-12-o3","label":"Demand a fair baseline"}],"task":"State the verdict in one sentence: the 99% score was leakage from duplicated blocks crossing the split, not real skill -- and the honest, properly isolated number is far lower, though not zero."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-the-split-12-o1","mission-ai-the-split-12-o2","mission-ai-the-split-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-the-split-01-o1-c1', 'orientation', 'Training data is not the whole dataset, and it is not something the model only sees after training is finished.', 10, 1),
  ('mission-ai-the-split-01-o1-c1', 'solution', 'Training data is the slice the model directly learns from, seeing its labels while its parameters adjust.', 20, 2),
  ('mission-ai-the-split-01-o2-c1', 'orientation', 'Ask whether memorizing rows and generalizing to new rows are the same thing.', 10, 1),
  ('mission-ai-the-split-01-o2-c1', 'solution', 'e2: a model graded on the rows it trained on can simply memorize them -- that proves nothing about how it would do on data it has never seen.', 20, 2),

  ('mission-ai-the-split-02-o1-c1', 'orientation', 'Validation data is not the pile the model directly learns its parameters from.', 10, 1),
  ('mission-ai-the-split-02-o1-c1', 'solution', 'Validation data checks and tunes a model during development, kept separate from training and from the final test set.', 20, 2),
  ('mission-ai-the-split-02-o2-c1', 'orientation', 'Ask what happens to an estimate once choices keep getting adjusted specifically to make that estimate look better.', 10, 1),
  ('mission-ai-the-split-02-o2-c1', 'solution', 'Repeatedly tuning against the same validation scores lets information about validation quietly leak into the model''s choices -- its score stops being an honest estimate of true unseen performance.', 20, 2),

  ('mission-ai-the-split-03-o1-c1', 'orientation', 'Only one of the three piles is allowed to be looked at just once.', 10, 1),
  ('mission-ai-the-split-03-o1-c1', 'solution', 'Test data is held back untouched until every tuning decision is finished, then evaluated exactly once to estimate real performance.', 20, 2),
  ('mission-ai-the-split-03-o2-c1', 'orientation', 'Ask which pile parameters are adjusted against, which pile decisions are compared against, and which pile is only read once at the end.', 10, 1),
  ('mission-ai-the-split-03-o2-c1', 'solution', 'Training: adjusting parameters directly. Validation: comparing configurations, early-stopping. Test: the single final reported number.', 20, 2),

  ('mission-ai-the-split-04-o1-c1', 'orientation', 'Random splitting does not look at any column''s meaning, only at row order after shuffling.', 10, 1),
  ('mission-ai-the-split-04-o1-c1', 'solution', 'It shuffles all rows, then divides them into piles by percentage, blind to what any column contains.', 20, 2),
  ('mission-ai-the-split-04-o2-c1', 'orientation', 'Think about what happens to a class that only has 40 rows once those 40 rows get shuffled and cut three ways.', 10, 1),
  ('mission-ai-the-split-04-o2-c1', 'solution', 'e2: with only 40 rare-class rows split randomly, at least one pile can end up with almost none of them, or none at all.', 20, 2),

  ('mission-ai-the-split-05-o1-c1', 'orientation', 'The word stratified refers to layers, or proportions, of a class -- not to size or timing.', 10, 1),
  ('mission-ai-the-split-05-o1-c1', 'solution', 'Stratification preserves each class''s proportion across training, validation and test, rather than leaving it to chance.', 20, 2),
  ('mission-ai-the-split-05-o2-c1', 'orientation', 'A roughly balanced 50/50 split can survive plain random splitting fairly safely. A severe imbalance usually cannot.', 10, 1),
  ('mission-ai-the-split-05-o2-c1', 'solution', 'e2: at a 96/4 split, a plain random split risks starving one pile of the rare 4% entirely -- stratification is what protects against that.', 20, 2),

  ('mission-ai-the-split-06-o1-c1', 'orientation', 'Think about what the future could teach a model about the past that it would never actually have access to at prediction time.', 10, 1),
  ('mission-ai-the-split-06-o1-c1', 'solution', 'A random split can mix future rows into training and past rows into test -- the model learns from information it would never actually have at real prediction time, inflating its scores.', 20, 2),
  ('mission-ai-the-split-06-o2-c1', 'orientation', 'Ask whether the scenario is large and balanced with no order to preserve, rare in its outcome of interest, or genuinely ordered by time.', 10, 1),
  ('mission-ai-the-split-06-o2-c1', 'solution', 'Random: large, balanced, no order. Stratified: a rare class that needs protecting. Time-based: genuine chronological order that must never be shuffled across.', 20, 2),

  ('mission-ai-the-split-07-o1-c1', 'orientation', 'Leakage is not about missing or duplicate data by itself -- it is about information reaching where it should not.', 10, 1),
  ('mission-ai-the-split-07-o1-c1', 'solution', 'Leakage is any information reaching training or evaluation that would not actually be available under fair, honest conditions.', 20, 2),
  ('mission-ai-the-split-07-o2-c1', 'orientation', 'The duplicates existing somewhere is not the leak by itself. What happens to them during splitting is.', 10, 1),
  ('mission-ai-the-split-07-o2-c1', 'solution', 'e2: the quick split shuffled everything, including known duplicated blocks, before dividing into training and test -- letting the same underlying record land in both piles.', 20, 2),

  ('mission-ai-the-split-08-o1-c1', 'orientation', 'Ask when the feature''s value would actually be known in the real world, relative to the outcome.', 10, 1),
  ('mission-ai-the-split-08-o1-c1', 'solution', 'Target leakage is a feature that only becomes known, or only exists, after the outcome has already happened -- it encodes the answer instead of predicting it.', 20, 2),
  ('mission-ai-the-split-08-o2-c1', 'orientation', 'A feature set only once a case is closed cannot have existed at prediction time.', 10, 1),
  ('mission-ai-the-split-08-o2-c1', 'solution', 'e2: discharge_summary_flag is only set after the outcome is already known, so it leaks the target directly.', 20, 2),

  ('mission-ai-the-split-09-o1-c1', 'orientation', 'The shift is about the population the data represents, not about formatting or column types.', 10, 1),
  ('mission-ai-the-split-09-o1-c1', 'solution', 'Distribution shift is a mismatch between the population a model trained on and the population it is now being evaluated or used on.', 20, 2),
  ('mission-ai-the-split-09-o2-c1', 'orientation', 'Matching column names does not guarantee matching underlying values.', 10, 1),
  ('mission-ai-the-split-09-o2-c1', 'solution', 'e1: the earliest and most recent recovery batches show meaningfully different feature distributions -- a real shift, not just a formatting difference.', 20, 2),

  ('mission-ai-the-split-10-o1-c1', 'orientation', 'A number needs something to be compared against before it can be called good or bad.', 10, 1),
  ('mission-ai-the-split-10-o1-c1', 'solution', 'A baseline is the simplest reasonable model available -- a real model''s score only means something once it clears the baseline by a real margin.', 20, 2),
  ('mission-ai-the-split-10-o2-c1', 'orientation', 'Compare the model''s score directly to what the simplest possible guess would already achieve.', 10, 1),
  ('mission-ai-the-split-10-o2-c1', 'solution', 'e3: a baseline of 90% from just guessing the majority class means the model''s 91% barely beats doing nothing meaningful -- the number alone was misleading.', 20, 2),

  ('mission-ai-the-split-11-o1-c1', 'orientation', 'Confidence is not the same as verifiability.', 10, 1),
  ('mission-ai-the-split-11-o1-c1', 'solution', 'Reproducibility needs a fixed random seed, a versioned dataset, and a recorded configuration -- enough for the same run to be repeated and checked.', 20, 2),
  ('mission-ai-the-split-11-o2-c1', 'orientation', 'Trace what happens if this function is called twice on the same data without ever passing a fixed seed.', 10, 1),
  ('mission-ai-the-split-11-o2-c1', 'concept', 'A random shuffle with no fixed random_state produces a different order every call, so two runs on the same data would split it differently.', 20, 2),
  ('mission-ai-the-split-11-o2-c1', 'solution', 'The shuffled = data.sample(frac=1) line has no random_state set, so the split is different every run -- pass a fixed random_state to make it reproducible.', 30, 3),

  ('mission-ai-the-split-12-o1-c1', 'orientation', 'A real split must respect that duplicated blocks belong together, not just cut the file 80/20 blind.', 10, 1),
  ('mission-ai-the-split-12-o1-c1', 'solution', 'e1: the split shuffled every row together and cut 80/20 with no regard for underlying record or recovery block, which is exactly the setup that lets the same duplicated record land in both training and test.', 20, 2),
  ('mission-ai-the-split-12-o2-c1', 'orientation', 'Look for the evidence that actually cross-references training against test, not just evidence that duplicates exist somewhere.', 10, 1),
  ('mission-ai-the-split-12-o2-c1', 'solution', 'e2: cross-referencing the piles shows duplicated-block records present in both training and test -- the model was effectively tested on rows it had already memorized during training.', 20, 2),
  ('mission-ai-the-split-12-o3-c1', 'orientation', 'Compare the model''s honest, re-split score against a real baseline, not against the original 99%.', 10, 1),
  ('mission-ai-the-split-12-o3-c1', 'solution', 'e2: after removing duplicates and re-splitting cleanly, the same model scores 76% against a 71% majority-class baseline -- a small, genuine improvement, nowhere near the fake 99%.', 20, 2),
  ('mission-ai-the-split-12-o4-c1', 'orientation', 'Weigh all three audits together before naming the verdict.', 15, 1),
  ('mission-ai-the-split-12-o4-c1', 'solution', 'The 99% score was leakage: duplicated blocks crossed from training into test, inflating the number. A fair, properly isolated split puts the model at roughly 76% against a 71% baseline -- real, modest skill, not the number the team got excited about.', 25, 2);
